changeSet.sql:
alter table zugriff_protokoll add constraint zugriff_protokoll_rolle_ck
    check (rolle in ('INHABER', 'MITARBEITER', 'TREUHAENDER', 'GESCHAEFTSSTELLE'));
alter table zugriff_protokoll add constraint zugriff_protokoll_aktion_ck
    check (aktion in ('ERFASSEN', 'ANZEIGEN', 'HERUNTERLADEN', 'AENDERN', 'BESTAETIGEN', 'VERWERFEN',
        'WIEDERHOLEN', 'EXPORTIEREN', 'VERWEIGERT', 'SPERRE_KONFLIKT', 'WISSEN_ANZEIGEN',
        'WISSEN_ANNEHMEN', 'WISSEN_VERWERFEN', 'WISSEN_INGEST', 'WISSEN_LINT'));
alter table zugriff_protokoll add constraint zugriff_protokoll_details_ck
    check (details is null or jsonb_typeof(details) = 'object');

create trigger zugriff_protokoll_nur_einfuegen before update or delete on zugriff_protokoll
    for each row execute function zugriff_protokoll_nur_einfuegen();
create trigger zugriff_protokoll_kein_truncate before truncate on zugriff_protokoll
    for each statement execute function zugriff_protokoll_nur_einfuegen();
